def evaluate(expr: str) -> float:
    tokens = []
    i = 0
    n = len(expr)

    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
        elif c.isascii() and c.isdigit():
            start = i
            while i < n and expr[i].isascii() and expr[i].isdigit():
                i += 1
            if i < n and expr[i] == '.':
                i += 1
                while i < n and expr[i].isascii() and expr[i].isdigit():
                    i += 1
            tokens.append(('number', expr[start:i]))
        elif c == '.':
            if i + 1 >= n or not (expr[i + 1].isascii() and expr[i + 1].isdigit()):
                raise ValueError('Unknown character')
            start = i
            i += 1
            while i < n and expr[i].isascii() and expr[i].isdigit():
                i += 1
            tokens.append(('number', expr[start:i]))
        elif c in '+-*/()':
            tokens.append((c, c))
            i += 1
        else:
            raise ValueError(f'Unknown character: {c}')

    if not tokens:
        raise ValueError('Empty expression')

    values = []
    operators = []
    precedence = {'u-': 3, '*': 2, '/': 2, '+': 1, '-': 1}
    right_associative = {'u-'}

    def apply_operator():
        op = operators.pop()
        if op == 'u-':
            if not values:
                raise ValueError('Malformed expression')
            values.append(-values.pop())
            return
        if len(values) < 2:
            raise ValueError('Malformed expression')
        right = values.pop()
        left = values.pop()
        if op == '+':
            values.append(left + right)
        elif op == '-':
            values.append(left - right)
        elif op == '*':
            values.append(left * right)
        else:
            if right == 0:
                raise ZeroDivisionError('division by zero')
            values.append(left / right)

    expect_operand = True
    for kind, text in tokens:
        if kind == 'number':
            if not expect_operand:
                raise ValueError('Missing operator')
            values.append(float(text))
            expect_operand = False
        elif kind == '(':
            if not expect_operand:
                raise ValueError('Missing operator')
            operators.append('(')
        elif kind == ')':
            if expect_operand:
                raise ValueError('Malformed expression')
            while operators and operators[-1] != '(':
                apply_operator()
            if not operators:
                raise ValueError('Unbalanced parentheses')
            operators.pop()
            expect_operand = False
        elif kind == '-' and expect_operand:
            operators.append('u-')
        elif kind in '+-*/':
            if expect_operand:
                raise ValueError('Malformed expression')
            while (operators and operators[-1] != '(' and
                   (precedence[operators[-1]] > precedence[kind] or
                    (precedence[operators[-1]] == precedence[kind] and
                     kind not in right_associative))):
                apply_operator()
            operators.append(kind)
            expect_operand = True
        else:
            raise ValueError('Malformed expression')

    if expect_operand:
        raise ValueError('Trailing operator')
    while operators:
        if operators[-1] == '(':
            raise ValueError('Unbalanced parentheses')
        apply_operator()
    if len(values) != 1:
        raise ValueError('Malformed expression')
    return float(values[0])
